mapper.select:
select id, connector_name as name, api_url as apiUrl, api_key as apiKey, model,
       supported_types as supportedTypes,
       request_params as requestParams, enabled, is_default as defaultConnector,
       create_time as createTime, update_time as updateTime
from ${table}
where id = #{id}

mapper.update:
update ${table}
set connector_name = #{config.name},
    api_url = #{config.apiUrl},
    api_key = #{config.apiKey},
    model = #{config.model},
    supported_types = #{config.supportedTypes},
    request_params = #{config.requestParams},
    enabled = #{config.enabled},
    update_time = #{config.updateTime}
where id = #{config.id}
